func:
flow.set('selected_patient', msg.payload || 'patient001');
node.status({fill: "blue", shape: "dot", text: "Pasien dipilih: " + (msg.payload || 'patient001')});
return null;

let patientId = flow.get('selected_patient') || 'patient001';
let sessionId = 'session-' + Date.now();
let deviceId = env.get('HEALTH_DEVICE_ID') || flow.get('HEALTH_DEVICE_ID') || 'device01';

let sessionData = {
    status: 'authorized',
    session_id: sessionId,
    patient_id: patientId,
    device_id: deviceId,
    started_at: new Date().toISOString()
};

// Simpan di context sebagai sesi aktif
flow.set('active_session', sessionData);
flow.set('session_measurements', []); // Reset rekaman sesi

node.status({fill: "green", shape: "dot", text: "Sesi aktif: " + sessionId});

// 1. Kirim MQTT otorisasi ke topik ESP32
let mqttMsg = {
    topic: 'health/' + deviceId + '/session',
    payload: JSON.stringify({
        status: 'authorized',
        session_id: sessionId,
        patient_id: patientId
    })
};

// 2. Kirim update status ke UI
let uiMsg = {
    payload: {
        active: true,
        session_id: sessionId,
        patient_id: patientId,
        started_at: sessionData.started_at,
        message: 'Sesi Aktif: Silakan letakkan jari pada sensor MAX30102'
    }
};

return [mqttMsg, uiMsg];

let deviceId = env.get('HEALTH_DEVICE_ID') || flow.get('HEALTH_DEVICE_ID') || 'device01';
let activeSession = flow.get('active_session');

flow.set('active_session', null);
node.status({fill: "red", shape: "ring", text: "Sesi dihentikan"});

// 1. Kirim MQTT stop ke ESP32
let mqttMsg = {
    topic: 'health/' + deviceId + '/session',
    payload: JSON.stringify({ status: 'stop' })
};

// 2. Kirim update status ke UI
let uiMsg = {
    payload: {
        active: false,
        session_id: activeSession ? activeSession.session_id : '-',
        patient_id: activeSession ? activeSession.patient_id : '-',
        ended_at: new Date().toISOString(),
        message: 'Sesi Pemeriksaan Telah Dihentikan'
    }
};

return [mqttMsg, uiMsg];

let active = flow.get('active_session');
if (!active) {
    // Buat dummy sesi jika belum ada
    active = {
        session_id: 'session-demo-sim',
        patient_id: 'patient001',
        device_id: 'device01'
    };
    flow.set('active_session', active);
}

// Simulasi variasi denyut jantung 70-85 BPM dan SpO2 96-99%
let hr = Math.floor(Math.random() * (85 - 72 + 1)) + 72;
let spo2 = Math.floor(Math.random() * (99 - 96 + 1)) + 96;

msg.payload = {
    device_id: active.device_id || 'device01',
    patient_id: active.patient_id || 'patient001',
    session_id: active.session_id,
    finger_detected: true,
    heart_rate_bpm: hr,
    spo2_percent: spo2,
    hr_valid: true,
    spo2_valid: true,
    timestamp_ms: Date.now()
};
return msg;

let d = msg.payload;
if (typeof d === 'string') {
    try { d = JSON.parse(d); } catch(e) { return null; }
}

if (!d || !d.session_id || !d.device_id) {
    node.status({fill: "yellow", shape: "ring", text: "Data diabaikan: session_id/device_id kosong"});
    return null;
}

let active = flow.get('active_session');

// Validasi Sesi: Pastikan sesi aktif di database/backend cocok
if (!active || active.session_id !== d.session_id) {
    node.status({fill: "yellow", shape: "ring", text: "Sesi tidak terdaftar/kadaluarsa"});
    return null;
}

// Gunakan patient_id dari sesi terdaftar (bukan mempercayai mentah payload)
let patientId = active.patient_id;
let hr = (d.hr_valid && d.heart_rate_bpm > 0) ? d.heart_rate_bpm : null;
let spo2 = (d.spo2_valid && d.spo2_percent > 0) ? d.spo2_percent : null;
let finger = d.finger_detected ? true : false;
let nowStr = new Date().toLocaleTimeString('id-ID');

// Simpan rekaman pengukuran ke context history (memenuhi SQLite requirements)
let records = flow.get('session_measurements') || [];
let newRec = {
    id: records.length + 1,
    time: nowStr,
    session_id: d.session_id,
    patient_id: patientId,
    heart_rate: hr || 0,
    spo2: spo2 || 0,
    finger: finger
};
records.unshift(newRec);
if (records.length > 50) records.pop();
flow.set('session_measurements', records);

node.status({fill: "green", shape: "dot", text: "BPM: " + (hr || '-') + " | SpO2: " + (spo2 || '-') + "%"});

// 1. Output BPM Gauge
let msgHr = { payload: hr || 0 };

// 2. Output SpO2 Gauge
let msgSpo2 = { payload: spo2 || 0 };

// 3. Output Status Device / Finger
let msgStatus = {
    payload: {
        device_id: d.device_id,
        finger_detected: finger,
        hr_valid: d.hr_valid,
        spo2_valid: d.spo2_valid,
        last_seen: nowStr
    }
};

// 4. Output Chart Vitals (multi-series)
let msgChartHr = { payload: hr || 0, topic: "Denyut Nadi (BPM)" };
let msgChartSpo2 = { payload: spo2 || 0, topic: "Saturasi Oksigen (%)" };

// 5. Output History Table HTML
let rowsHtml = "";
records.slice(0, 10).forEach(r => {
    let hrColor = (r.heart_rate >= 60 && r.heart_rate <= 100) ? "#10b981" : "#f59e0b";
    let spo2Color = (r.spo2 >= 95) ? "#10b981" : (r.spo2 >= 90 ? "#f59e0b" : "#ef4444");
    rowsHtml += `<tr>
      <td>` + r.time + `</td>
      <td><code>` + r.session_id.substring(0, 16) + `...</code></td>
      <td><b>` + r.patient_id + `</b></td>
      <td style="color: ` + hrColor + `; font-weight: bold;">` + r.heart_rate + ` BPM</td>
      <td style="color: ` + spo2Color + `; font-weight: bold;">` + r.spo2 + ` %</td>
      <td>` + (r.finger ? '<span class="badge-finger-yes">Terdeteksi</span>' : '<span class="badge-finger-no">Lepas</span>') + `</td>
    </tr>`;
});

let tableHtml = `
<table class="history-tbl">
  <thead>
    <tr>
      <th>Waktu</th>
      <th>ID Sesi</th>
      <th>Pasien</th>
      <th>Heart Rate</th>
      <th>SpO2</th>
      <th>Sensor Jari</th>
    </tr>
  </thead>
  <tbody>` + (rowsHtml || '<tr><td colspan="6" style="text-align: center; color: #94a3b8;">Belum ada pengukuran</td></tr>') + `</tbody>
</table>`;
let msgTable = { payload: tableHtml };

return [msgHr, msgSpo2, msgStatus, msgChartHr, msgChartSpo2, msgTable];

let s = msg.payload;
if (typeof s === 'string') {
    try { s = JSON.parse(s); } catch(e) { s = { detail: s }; }
}
msg.payload = {
    status: s.status || 'online',
    detail: s.detail || 'Sensor siap',
    device_id: s.device_id || 'device01',
    time: new Date().toLocaleTimeString('id-ID')
};
return msg;

msg.payload = {
    device_id: 'device01',
    status: msg.payload.active ? 'Sesi Aktif' : 'Menunggu Sesi',
    detail: msg.payload.message,
    finger_detected: false
};
return msg;
